-- Animated backgrounds replace Card Themes and Profile Effects.
--
-- 1. Everyone who paid for a card_theme / profile_effect item gets it back as a `refund` ledger row
--    in the currency they paid with: the full price for a direct purchase, or the item's share of
--    the bundle price (by the items' Miles prices) when it came in a bundle. Free claims and
--    grants have nothing to refund.
-- 2. Those items, their entitlements and equip rows are deleted.
-- 3. The seeded bundles swap them for backgrounds (Night Owl: Shooting Stars; Halloween gains Fog).
-- 4. 30 background products are seeded (slot `background`). Their ids match the website's
--    registry (src/components/backgrounds/index.ts). Card stills are generated later from the
--    store admin, so the cards keep their normal backdrop until then.
INSERT INTO `store_credit_ledger` (`user_id`, `delta`, `kind`, `currency`, `product_id`, `note`, `created_at`)
SELECT `user_id`, `delta`, 'refund', `currency`, `product_id`, `note`, CAST(strftime('%s', 'now') AS INTEGER) * 1000 FROM (
  SELECT
    e.`user_id` AS `user_id`,
    l.`currency` AS `currency`,
    e.`product_id` AS `product_id`,
    'Refund: ' || p.`name` || ' was retired' AS `note`,
    CASE
      WHEN l.`product_id` = e.`product_id` THEN -l.`delta`
      ELSE COALESCE(CAST(ROUND(-l.`delta` * COALESCE(p.`price_miles`, 0) * 1.0 / NULLIF((
        SELECT SUM(COALESCE(p2.`price_miles`, 0))
        FROM `store_entitlements` e2
        JOIN `store_products` p2 ON p2.`id` = e2.`product_id`
        WHERE e2.`ledger_id` = l.`id` AND e2.`product_id` <> l.`product_id`
      ), 0)) AS INTEGER), 0)
    END AS `delta`
  FROM `store_entitlements` e
  JOIN `store_products` p ON p.`id` = e.`product_id`
  JOIN `store_credit_ledger` l ON l.`id` = e.`ledger_id`
  WHERE e.`product_id` IN (SELECT `id` FROM `store_products` WHERE `type` = 'cosmetic' AND json_extract(`config_json`, '$.slot') IN ('card_theme', 'profile_effect')) AND l.`delta` < 0
) WHERE `delta` > 0;
--> statement-breakpoint
DELETE FROM `store_entitlements` WHERE `product_id` IN (SELECT `id` FROM `store_products` WHERE `type` = 'cosmetic' AND json_extract(`config_json`, '$.slot') IN ('card_theme', 'profile_effect'));
--> statement-breakpoint
DELETE FROM `user_cosmetics_equipped` WHERE `slot` IN ('card_theme', 'profile_effect');
--> statement-breakpoint
DELETE FROM `store_products` WHERE `id` IN (SELECT `id` FROM `store_products` WHERE `type` = 'cosmetic' AND json_extract(`config_json`, '$.slot') IN ('card_theme', 'profile_effect'));
